Object.assign(demoTitles,{'net-layers':'计网：从应用消息到数据帧','net-subnet':'计网：子网计算与网关选择','net-dns':'计网：DNS 查询与缓存','net-tcp':'计网：TCP 三次握手与失败现象','net-http':'计网：HTTPS 请求经过哪些步骤'});
Object.assign(demoState,{netIP:'10.0.0.10',netTarget:'10.0.1.20',netPrefix:24,dnsCached:false,tcpCase:'normal',httpCode:'200'});
const previousDemoMax=demoMax,previousChangeDemo=changeDemo,previousDemoForLesson=demoForLesson;
function isNetworkDemo(){return demoState.type.startsWith('net-');}
demoMax=function(){if(!isNetworkDemo())return previousDemoMax();return {'net-layers':5,'net-subnet':2,'net-dns':demoState.dnsCached?2:5,'net-tcp':demoState.tcpCase==='normal'?3:2,'net-http':5}[demoState.type];};
demoForLesson=function(c){return c.networkDemo||previousDemoForLesson(c);};
changeDemo=function(el){if(!el.id.startsWith('demo-net-'))return previousChangeDemo(el);pauseDemo();if(el.id==='demo-net-ip'||el.id==='demo-net-target'){if(!parseIPv4(el.value)){el.setCustomValidity?.('请输入四段 0–255 的 IPv4 地址');el.reportValidity?.();return;}el.setCustomValidity?.('');demoState[el.id==='demo-net-ip'?'netIP':'netTarget']=el.value.trim();}if(el.id==='demo-net-prefix')demoState.netPrefix=Number(el.value);if(el.id==='demo-net-cached')demoState.dnsCached=el.checked;if(el.id==='demo-net-tcp')demoState.tcpCase=el.value;if(el.id==='demo-net-code')demoState.httpCode=el.value;demoState.step=0;render();};
function parseIPv4(value){const p=String(value).trim().split('.');if(p.length!==4||p.some(x=>!/^\d{1,3}$/.test(x)||Number(x)>255||Number(x)<0))return null;return p.map(Number);}
function ipNumber(parts){return parts.reduce((n,x)=>(n*256+x)>>>0,0);}
function dotted(n){return [24,16,8,0].map(shift=>(n>>>shift)&255).join('.');}
function subnetModel(){const prefix=demoState.netPrefix,mask=(0xffffffff<<(32-prefix))>>>0,ip=ipNumber(parseIPv4(demoState.netIP)),target=ipNumber(parseIPv4(demoState.netTarget)),network=(ip&mask)>>>0,targetNetwork=(target&mask)>>>0,broadcast=(network|(~mask>>>0))>>>0;return {prefix,mask:dotted(mask),network:dotted(network),targetNetwork:dotted(targetNetwork),broadcast:dotted(broadcast),same:network===targetNetwork,hosts:2**(32-prefix)-2};}
function netArrow(){return '<div class="net-connector" aria-hidden="true"><svg viewBox="0 0 24 28"><path d="M12 2v21m-5-6 5 6 5-6" fill="none" stroke="currentColor" stroke-width="2"/></svg></div>';}
function netNode(title,detail,active=false){return `<div class="net-node ${active?'active':''}"><strong>${esc(title)}</strong><span>${esc(detail)}</span></div>`;}
function networkSketch(type){let content='';if(type==='net-layers'){content=[['应用层','HTTP / DNS：消息内容与规则'],['传输层','TCP / UDP：端口与传输机制'],['网络层','IP / 路由：跨网络寻址'],['链路层','以太网 / ARP：本链路下一跳']].map(([a,b])=>netNode(a,b)).join('');}if(type==='net-subnet'){content=netNode('本机 10.0.0.10/24','网络部分：10.0.0.0')+netArrow()+`<div class="net-branches">${netNode('同网段 10.0.0.20','通常直接寻找目标的链路地址')}${netNode('跨网段 10.0.1.20','通常通过合适路由的下一跳')}</div>`;}if(type==='net-dns'){content=netNode('应用查询域名','web.lab.test 的 A 记录')+netArrow()+netNode('递归解析器','先查缓存；未命中时继续查询')+netArrow()+netNode('得到 IPv4 地址','教学结果：10.0.0.20');}if(type==='net-tcp'){content=handshakeDiagram(3,'normal');}if(type==='net-http'){content=netNode('域名解析','找到服务的 IP')+netArrow()+netNode('TCP + TLS','建立连接并协商安全传输')+netArrow()+netNode('HTTP 请求与响应','读取状态码、响应头与业务内容');}return `<figure class="network-sketch"><figcaption>先看图，再理解文字</figcaption><div class="sketch-${type}">${content}</div><button class="secondary" data-action="open-demo" data-demo="${type}">打开可交互演示</button></figure>`;}
function layerDemo(){const step=demoState.step,levels=[['应用层','HTTP 请求消息','GET / HTTP/1.1','先确定应用要发送的内容。'],['传输层','TCP 段','端口 52344 → 80','加上传输层信息；TCP 还负责可靠、有序的字节流。'],['网络层','IP 包','10.0.0.10 → 10.0.0.20','加上 IP 寻址信息，并依据路由决定下一跳。'],['链路层','以太网帧','当前链路的源与下一跳 MAC','把 IP 包放入本链路的数据帧；跨路由器后链路头部会变化。']];return `<div class="demo-lead"><h2>同一次请求，被不同层各管一部分。</h2><p>从应用消息开始，逐层添加本层信息。接收端再按协议处理各层内容。</p></div><div class="network-layer-list">${levels.map(([name,unit,fields],i)=>`<div class="network-layer ${step===i+1?'active':step>i+1?'done':''}"><span class="layer-number">${i+1}</span><div><strong>${name}</strong><p>${unit}</p></div><code>${fields}</code></div>`).join('')}</div><div class="packet-envelope"><span>用嵌套盒子理解“封装”</span><div class="frame-box">链路头部 <div>IP 头部 <div>TCP 头部 <strong>HTTP 消息</strong></div></div></div></div><div class="explain-panel" aria-live="polite"><strong>${step===0?'从消息内容开始':step===5?'接收端逐层处理':levels[step-1][0]}</strong><p>${step===0?'四层各有职责。IP 和端口不是同一件事。':step===5?'接收端验证并处理链路、IP、TCP 信息，应用最终获得 HTTP 消息。中间路由器主要按网络层转发，不必处理你的业务 SQL。':levels[step-1][3]}</p></div><p class="demo-footnote">简化为以太网、IPv4、TCP、HTTP 的普通路径；不同链路、隧道、NAT 和其他协议可能改变细节。这些层名不与 OSI 七层严格一一对应。</p>`;}
function subnetDemo(){const m=subnetModel(),step=demoState.step;return `<div class="demo-lead"><h2>把地址与掩码做按位与，得到网络部分。</h2><p>改变本机、目标和前缀长度。比较网络部分，观察同网段或跨网段的示意路径。</p></div><div class="demo-inputs subnet-inputs"><label>本机 IPv4<input id="demo-net-ip" value="${esc(demoState.netIP)}" inputmode="decimal" autocomplete="off"></label><label>目标 IPv4<input id="demo-net-target" value="${esc(demoState.netTarget)}" inputmode="decimal" autocomplete="off"></label><label>前缀长度<select id="demo-net-prefix">${[8,16,24,26,30].map(n=>`<option value="${n}" ${m.prefix===n?'selected':''}>/${n}</option>`).join('')}</select></label></div><div class="subnet-math"><div><span>子网掩码</span><code>${m.mask}</code></div><div><span>本机网络部分</span><code>${step>=1?m.network:'等待计算'}</code></div><div><span>目标网络部分</span><code>${step>=1?m.targetNetwork:'等待计算'}</code></div><div><span>本子网广播地址</span><code>${step>=1?m.broadcast:'等待计算'}</code></div></div><div class="net-route">${netNode('本机',demoState.netIP,true)}${netArrow()}${step>=2?m.same?netNode('同网段直达示意','寻找目标 '+demoState.netTarget+' 的链路地址',true):netNode('交给路由下一跳','由合适路由选择网关；此处不推导网关地址',true):netNode('等待比较','检查两个网络部分是否相同')}${netArrow()}${netNode('目标主机',demoState.netTarget,step>=2)}</div><div class="explain-panel" aria-live="polite"><strong>${step===0?'读出地址和掩码':step===1?'计算网络部分':m.same?'网络部分相同':'网络部分不同'}</strong><p>${step===0?'前缀位是网络部分，其余位是主机部分。':step===1?`本机与掩码按位与得到 ${m.network}，目标得到 ${m.targetNetwork}。`:m.same?'此简化场景属于同一子网，通常直接在本链路寻找目标。':'此简化场景跨子网，通常经路由表选择下一跳。网关 IP 不能只凭掩码自动推导。'}</p></div><p class="demo-footnote">仅演示 /8–/30 的普通子网。理论常规主机地址数量 ${m.hosts.toLocaleString()}，不含网络和广播地址；真实设备仍以路由表、配置与安全策略为准。</p>`;}
function dnsSteps(){return demoState.dnsCached?[['应用发起查询','客户端向配置的解析器查询 web.lab.test 的 A 记录。'],['缓存命中','解析器已有未过期答案，不再查询根、顶级域与权威服务器。'],['返回地址','把教学地址 10.0.0.20 返回应用，应用继续建连。']]:[['应用发起查询','客户端向配置的递归解析器询问地址。'],['检查缓存','没有可用缓存，解析器开始迭代查询。'],['询问根服务器','获得顶级域相关服务器的指引，而不是立即获得最终主机 IP。'],['询问顶级域服务器','获得对应权威服务器的指引。'],['询问权威服务器','获得该域名的教学 A 记录答案。'],['缓存并返回地址','按 TTL 缓存答案并返回 10.0.0.20；浏览器继续连接。']];}
function dnsDemo(){const steps=dnsSteps(),step=demoState.step;return `<div class="demo-lead"><h2>解析器替你找到答案，缓存减少重复查找。</h2><p>切换缓存命中，看看为什么第二次解析常常更快。</p></div><div class="demo-inputs"><label class="check-input"><input id="demo-net-cached" type="checkbox" ${demoState.dnsCached?'checked':''}>解析器已有未过期答案</label></div><div class="dns-flow">${steps.map(([name,detail],i)=>`<div class="dns-event ${i===step?'active':i<step?'done':''}"><span>${i+1}</span><div><strong>${name}</strong><p>${detail}</p></div></div>`).join('')}</div><div class="explain-panel" aria-live="polite"><strong>${steps[step][0]}</strong><p>${steps[step][1]}</p></div><p class="demo-footnote">这里的 .test 名称仅用于保留测试域中的教学模拟，不会在真实公共 DNS 上这样解析。图示忽略本机 hosts、stub 缓存、CNAME、DNSSEC 和错误分支；公网迭代流程是概念示意。</p>`;}
function handshakeDiagram(step,kind){const messages=kind==='normal'?[['SYN · seq=100','right'],['SYN + ACK · seq=500, ack=101','left'],['ACK · seq=101, ack=501','right']]:kind==='refused'?[['SYN · 请求连接','right'],['RST + ACK · 拒绝连接','left']]:[['SYN · 请求连接','right'],['没有收到回应 · 可能重传与等待','none']];return `<div class="handshake-diagram"><div class="peer-titles"><strong>客户端</strong><strong>服务器</strong></div>${messages.map(([text,direction],i)=>`<div class="handshake-message ${i<step?'revealed':'waiting'}"><span>${i+1}. ${text}</span><svg viewBox="0 0 600 30" preserveAspectRatio="none" aria-hidden="true" class="${direction}"><path d="M10 15H585m-10-8 10 8-10 8" fill="none" stroke="currentColor" stroke-width="2" ${direction==='none'?'stroke-dasharray="7 6"':''}/></svg></div>`).join('')}</div>`;}
function tcpDemo(){const step=demoState.step,kind=demoState.tcpCase,notes=kind==='normal'?['服务在 LISTEN 等待；客户端尚未建连。','客户端发送 SYN，请求同步连接的序列号。','服务端发送 SYN+ACK，确认客户端 SYN 并发送自己的 SYN。','客户端 ACK 确认服务端 SYN；常见路径下双方完成连接建立。']:kind==='refused'?['准备向目标端口发起连接。','客户端发送 SYN。','收到拒绝连接的 RST 响应；目标未监听或策略主动拒绝等情况都需继续核实。']:['准备向目标端口发起连接。','客户端发送 SYN。','没有收到回应；可能是丢包、路径问题或静默丢弃，不能只凭超时判断具体原因。'];return `<div class="demo-lead"><h2>建立 TCP 连接，要确认双方都准备好。</h2><p>选择正常、拒绝或无回应，逐步观察不同现象。</p></div><div class="demo-inputs"><label>连接情景<select id="demo-net-tcp">${[['normal','正常三次握手'],['refused','收到拒绝连接'],['timeout','没有收到回应']].map(([v,t])=>`<option value="${v}" ${v===kind?'selected':''}>${t}</option>`).join('')}</select></label></div>${handshakeDiagram(step,kind)}<div class="connection-status"><span>客户端</span><strong>${step===0?'CLOSED':kind==='normal'&&step===3?'ESTABLISHED':step===demoMax()&&kind!=='normal'?'本次连接失败':'SYN-SENT / 等待确认'}</strong><span>应用请求</span><strong>${kind==='normal'&&step===3?'可以继续发送应用数据':'尚未验证应用业务'}</strong></div><div class="explain-panel" aria-live="polite"><strong>${step?'第 '+step+' 步':'准备连接'}</strong><p>${notes[step]}</p></div><p class="demo-footnote">图示省略重传、窗口、选项和同时打开等细节。收到拒绝与无响应超时不是同一种证据；TCP 建连成功仍不能证明 HTTP 或数据库业务正常。</p>`;}
function httpDemo(){const step=demoState.step,list=[['DNS','域名解析为服务地址'],['TCP','建立传输连接'],['TLS','协商加密并验证服务证书'],['HTTP 请求','发送请求方法、路径与头部'],['HTTP 响应','接收状态码、头部和内容']];return `<div class="demo-lead"><h2>HTTPS 请求由多个环节一起完成。</h2><p>先把连接建立起来，再读 HTTP 响应。返回 404 或 500 时，请求已经到达了应用层响应环节。</p></div><div class="demo-inputs"><label>模拟响应<select id="demo-net-code">${[['200','200 OK'],['404','404 Not Found'],['500','500 Internal Server Error']].map(([v,t])=>`<option value="${v}" ${v===demoState.httpCode?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="https-chain">${list.map(([name,detail],i)=>`<div class="https-step ${i<step?'done':i===step?'active':''}"><span>${i+1}</span><div><strong>${name}</strong><p>${detail}</p></div></div>`).join('')}</div><div class="http-outcome"><span>目标： https://web.lab.test/</span><strong>${step===5?'HTTP/1.1 '+{'200':'200 OK','404':'404 Not Found','500':'500 Internal Server Error'}[demoState.httpCode]:'等待各环节完成'}</strong></div><div class="explain-panel" aria-live="polite"><strong>${step===5?'按响应继续判断':list[step][0]}</strong><p>${step===5?demoState.httpCode==='200'?'本次请求成功；还需检查实际业务链路和持续运行情况。':demoState.httpCode==='404'?'已经获得 HTTP 响应，继续检查请求路径、应用路由和目标资源。':'服务端返回错误；结合应用日志、依赖和时间线排查，而不是直接断言 DNS 故障。':list[step][1]}</p></div><p class="demo-footnote">这里演示常见 HTTP/1.1 over TLS over TCP；HTTP/2 消息形式和 HTTP/3 over QUIC 有差异。复用连接、缓存或代理也会改变实际步骤；示例域名只用于教学。</p>`;}
function renderNetworkDemo(){const content={'net-layers':layerDemo,'net-subnet':subnetDemo,'net-dns':dnsDemo,'net-tcp':tcpDemo,'net-http':httpDemo}[demoState.type];return content();}
